/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["saubere-webapps"]={"Code in Funktionen und Dateien aufteilen":"تقسیم کد به تابع‌ها و فایل‌ها","Eine wartbare Aufgabenliste organisieren":"یک لست کارهای قابل نگهداری را سازمان دهید","Professioneller Code bleibt auch nach Monaten verständlich und veränderbar. Du lernst, Datenverarbeitung und Darstellung voneinander zu trennen.":"کد حرفه‌ای حتی بعد از چند ماه هم قابل فهم و قابل تغییر می‌ماند. یاد می‌گیرید پردازش داده و نمایش را از هم جدا کنید.","Verantwortung erkennen":"شناختن مسئولیت","Bei einer Aufgabenliste gibt es drei verschiedene Tätigkeiten: eine Aufgabe anlegen, sie speichern und sie anzeigen. Wenn du alle Schritte in einen einzigen Klick-Handler schreibst, musst du später an vielen Stellen gleichzeitig Änderungen vornehmen. Notiere zuerst, welche Aufgabe jede Funktion übernehmen soll. `aufgabeErstellen` erzeugt nur Daten und berührt die Webseite nicht. Diese Trennung macht die Funktion leicht zu verstehen und unabhängig testbar.":"در یک لست کارها سه کار مختلف هست: ساختن یک کار، ذخیرهٔ آن و نشان دادن آن. اگر همهٔ قدم‌ها را در یک Handler کلیک بنویسید، بعداً باید در جاهای زیادی هم‌زمان تغییر بدهید. اول یادداشت کنید که هر تابع کدام کار را به عهده بگیرد. `aufgabeErstellen` فقط داده می‌سازد و به صفحهٔ ویب دست نمی‌زند. این جدایی فهمیدن تابع را آسان و آزمایش آن را مستقل می‌کند.","Bei einer Aufgabenliste gibt es drei verschiedene Tätigkeiten: eine Aufgabe anlegen, sie speichern und sie anzeigen.":"در یک لست کارها سه کار مختلف هست: ساختن یک کار، ذخیرهٔ آن و نشان دادن آن.","Datenfunktion schreiben":"نوشتن تابع داده","Eine Werkstatt bewahrt Werkzeuge nach ihrem Zweck auf. `function aufgabeErstellen(text) { return { text, erledigt: false }; }` erhält einen Text und gibt ein neues Objekt zurück. Das Objekt enthält den Aufgabentext und den Status. Ein Funktionsname soll eine Handlung beschreiben. Übergib den Text als Parameter statt heimlich auf ein Eingabefeld zuzugreifen; so kann die Funktion auch in einem Test benutzt werden.":"یک ورکشاپ ابزارها را بر اساس کاربردشان نگه می‌دارد. `function aufgabeErstellen(text) { return { text, erledigt: false }; }` یک متن می‌گیرد و یک آبجکت تازه پس می‌دهد. آبجکت متن کار و وضعیت را دارد. نام یک تابع باید یک کار را توصیف کند. متن را به عنوان پارامتر بدهید، نه اینکه پنهانی به یک خانهٔ ورودی دسترسی پیدا کنید؛ به این ترتیب تابع در یک آزمایش هم قابل استفاده است.","Eine Werkstatt bewahrt Werkzeuge nach ihrem Zweck auf.":"یک ورکشاپ ابزارها را بر اساس کاربردشان نگه می‌دارد.","Darstellung getrennt halten":"جدا نگه داشتن نمایش","Die Anzeige ist wie ein Schaufenster: Sie zeigt Daten, erzeugt sie aber nicht selbst. `const aufgabe = aufgabeErstellen('Brief schreiben');` erzeugt das Objekt. `document.querySelector('#ausgabe').textContent = aufgabe.text;` schreibt den Text in ein Element. Wenn du später ein anderes Layout möchtest, bleibt die Datenfunktion unverändert. Prüfe mit einer zweiten Aufgabe, ob der gleiche Ablauf funktioniert.":"نمایش مثل یک ویترین است: داده‌ها را نشان می‌دهد، اما خودش آن‌ها را نمی‌سازد. `const aufgabe = aufgabeErstellen('Brief schreiben');` آبجکت را می‌سازد. `document.querySelector('#ausgabe').textContent = aufgabe.text;` متن را در یک عنصر می‌نویسد. اگر بعداً چیدمان دیگری بخواهید، تابع داده بدون تغییر می‌ماند. با یک کار دوم بررسی کنید که آیا همان روند کار می‌کند.","Die Anzeige ist wie ein Schaufenster: Sie zeigt Daten, erzeugt sie aber nicht selbst.":"نمایش مثل یک ویترین است: داده‌ها را نشان می‌دهد، اما خودش آن‌ها را نمی‌سازد.","Dateien sinnvoll benennen":"نام‌گذاری معقول فایل‌ها","Ein größeres Projekt kann `daten.js`, `ansicht.js` und `app.js` verwenden. `daten.js` enthält reine Datenfunktionen, `ansicht.js` kümmert sich um DOM-Elemente, `app.js` verbindet beide. Ein Modul importiert nur das, was es benötigt. Vermeide kreisförmige Abhängigkeiten, bei denen Dateien sich gegenseitig laden. Beginne bei einem kleinen Projekt mit wenigen klaren Dateien und teile erst auf, wenn eine Verantwortung deutlich erkennbar ist.":"یک پروژهٔ بزرگ‌تر می‌تواند از `daten.js`، `ansicht.js` و `app.js` استفاده کند. `daten.js` تابع‌های خالص داده را دارد، `ansicht.js` به عنصرهای DOM رسیدگی می‌کند و `app.js` هر دو را وصل می‌کند. یک ماژول فقط چیزی را وارد می‌کند که لازم دارد. از وابستگی‌های دایره‌ای که در آن فایل‌ها یکدیگر را بارگیری می‌کنند پرهیز کنید. در یک پروژهٔ کوچک با چند فایل روشن شروع کنید و فقط وقتی تقسیم کنید که یک مسئولیت روشن دیده شود.","Ein größeres Projekt kann `daten.js`, `ansicht.js` und `app.js` verwenden.":"یک پروژهٔ بزرگ‌تر می‌تواند از `daten.js`، `ansicht.js` و `app.js` استفاده کند.","Versteckte DOM-Abhängigkeit":"وابستگی پنهان به DOM","Falsch: `function aufgabeErstellen(){ return document.querySelector('#eingabe').value; }` ist ohne Webseite schwer testbar. Richtig: `function aufgabeErstellen(text){ return {text}; }` erhält seine Eingabe ausdrücklich als Parameter.":"اشتباه: `function aufgabeErstellen(){ return document.querySelector('#eingabe').value; }` بدون صفحهٔ ویب به سختی آزمایش می‌شود. درست: `function aufgabeErstellen(text){ return {text}; }` ورودی خود را صریحاً به عنوان پارامتر می‌گیرد.","Rückgabe vergessen":"فراموش کردن return","Falsch: `function aufgabeErstellen(text){ const a={text}; }` liefert `undefined`, obwohl ein Objekt erzeugt wird. Richtig: `function aufgabeErstellen(text){ return {text}; }` gibt das Ergebnis an den Aufrufer zurück.":"اشتباه: `function aufgabeErstellen(text){ const a={text}; }` ‏`undefined` می‌دهد، با اینکه یک آبجکت ساخته می‌شود. درست: `function aufgabeErstellen(text){ return {text}; }` نتیجه را به صدازننده پس می‌دهد.","Setze „Code in Funktionen und Dateien aufteilen“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«تقسیم کد به تابع‌ها و فایل‌ها» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Rufe aufgabeErstellen zweimal mit verschiedenen Texten auf und prüfe die zurückgegebenen Objekte.":"aufgabeErstellen را دو بار با متن‌های مختلف صدا بزنید و آبجکت‌های بازگشتی را بررسی کنید.","Die Oberfläche enthält die benötigten Elemente.":"صفحه عنصرهای لازم را دارد.","Die Technik wurde in JavaScript verwendet.":"این تکنیک در JavaScript به کار رفته است.","Welche Funktion lässt sich leichter testen?":"کدام تابع آسان‌تر آزمایش می‌شود؟","Ein Klick-Handler mit vielen globalen Variablen":"یک Handler کلیک با متغیرهای سراسری زیاد","Eine reine Datenfunktion":"یک تابع خالص داده","Ein unbenannter Seiteneffekt":"یک اثر جانبی بی‌نام","Eine Datenfunktion ist ohne Browser und versteckte Zustände leichter überprüfbar.":"یک تابع داده بدون براوزر و وضعیت‌های پنهان آسان‌تر بررسی می‌شود.","Diese Aussage widerspricht der erklärten Funktion.":"این جمله با کارکرد توضیح‌داده‌شده تناقض دارد.","Das stimmt mit der beschriebenen Technik überein.":"این با تکنیک توصیف‌شده جور می‌آید.","Wozu dient return?":"return برای چیست؟","Zum Ändern von CSS":"برای تغییر CSS","Zum Öffnen einer Datei":"برای باز کردن یک فایل","Zum Zurückgeben eines Wertes":"برای پس دادن یک مقدار","return gibt das erstellte Aufgabenobjekt an die aufrufende Stelle zurück.":"return آبجکت کار ساخته‌شده را به جایی که تابع صدا زده شده پس می‌دهد.","Welche Datei sollte die DOM-Anzeige verwalten?":"کدام فایل باید نمایش DOM را مدیریت کند؟","Die Darstellung gehört in eine eigene Datei, weil DOM-Code nicht Teil der Datenlogik sein muss.":"نمایش در یک فایل جداگانه جا دارد، چون کد DOM لازم نیست بخشی از منطق داده باشد.","Eingaben prüfen und XSS vermeiden":"بررسی ورودی‌ها و جلوگیری از XSS","Fremde Texte sicher anzeigen":"متن‌های بیگانه را مطمئن نشان دهید","Benutzereingaben dürfen die Struktur einer Webseite nicht unkontrolliert verändern. Du übst sichere Ausgabe und sinnvolle Eingabeprüfungen.":"ورودی‌های کاربر نباید ساختار یک صفحهٔ ویب را بی‌کنترول تغییر دهند. نمایش مطمئن و بررسی معقول ورودی را تمرین می‌کنید.","Unbekannte Eingaben erkennen":"شناختن ورودی‌های ناشناخته","Ein öffentliches Gästebuch nimmt Texte von Menschen entgegen, die du nicht kennst. Manche Eingaben enthalten Zeichen wie `<` oder `>`, die in HTML eine besondere Bedeutung haben. Ein fremder Text ist zunächst nur Dateninhalt und darf nicht als Anweisung behandelt werden. Lies einen Beispieltext ein und stelle dir vor, jemand fügt HTML-Tags statt eines Namens ein. Die sichere Anzeige muss auch dann verständlich bleiben.":"یک کتاب مهمانان عمومی متن‌هایی از آدم‌هایی می‌گیرد که آن‌ها را نمی‌شناسید. بعضی ورودی‌ها نشانه‌هایی مثل `<` یا `>` دارند که در HTML معنای خاصی دارند. یک متن بیگانه اول فقط محتوای داده است و نباید مثل دستور با آن رفتار شود. یک متن مثال را بخوانید و تصور کنید کسی به جای نام، تگ‌های HTML وارد می‌کند. نمایش مطمئن باید در آن صورت هم قابل فهم بماند.","Ein öffentliches Gästebuch nimmt Texte von Menschen entgegen, die du nicht kennst.":"یک کتاب مهمانان عمومی متن‌هایی از آدم‌هایی می‌گیرد که آن‌ها را نمی‌شناسید.","textContent verwenden":"استفاده از textContent","Auf einer Anzeigetafel wird eine Nachricht als Text gedruckt, nicht als Bauanleitung interpretiert. `ausgabe.textContent = eingabe;` setzt genau den Textinhalt eines Elements. Selbst wenn die Eingabe wie ein HTML-Tag aussieht, erzeugt diese Zuweisung daraus kein neues Bild oder Skript. Das ist für nutzergenerierte Texte der richtige Standard. Probiere normale Namen und eine Zeichenfolge mit spitzen Klammern aus.":"روی یک تابلوی نمایش، یک پیام به شکل متن چاپ می‌شود، نه به عنوان دستور ساخت تفسیر. `ausgabe.textContent = eingabe;` دقیقاً محتوای متنی یک عنصر را می‌گذارد. حتی اگر ورودی شبیه یک تگ HTML باشد، این انتساب از آن هیچ عکس یا اسکریپت تازه‌ای نمی‌سازد. این برای متن‌هایی که کاربران می‌سازند استاندارد درست است. نام‌های عادی و یک رشته با قوس‌های زاویه‌دار را امتحان کنید.","Auf einer Anzeigetafel wird eine Nachricht als Text gedruckt, nicht als Bauanleitung interpretiert.":"روی یک تابلوی نمایش، یک پیام به شکل متن چاپ می‌شود، نه به عنوان دستور ساخت تفسیر.","Gefährliche Alternative verstehen":"فهمیدن جایگزین خطرناک","`innerHTML` interpretiert den zugewiesenen String als HTML-Struktur. Wenn dieser String aus einer unkontrollierten Eingabe stammt, kann daraus Cross-Site-Scripting entstehen. Auch das Einfügen von HTML aus einer externen JSON-Datei ist nicht automatisch sicher. Verwende `createElement` und `textContent`, wenn du Elemente dynamisch bauen möchtest. Füge keine fremden Inhalte ungeprüft in HTML-Attribute oder URLs ein.":"`innerHTML` ‏String داده‌شده را به عنوان ساختار HTML تفسیر می‌کند. اگر این String از یک ورودی بی‌کنترول بیاید، ممکن است Cross-Site-Scripting پیدا شود. گذاشتن HTML از یک فایل JSON بیرونی هم خودکار مطمئن نیست. اگر می‌خواهید عنصرها را پویا بسازید، از `createElement` و `textContent` استفاده کنید. محتوای بیگانه را بدون بررسی در صفت‌های HTML یا URLها نگذارید.","`innerHTML` interpretiert den zugewiesenen String als HTML-Struktur.":"`innerHTML` ‏String داده‌شده را به عنوان ساختار HTML تفسیر می‌کند.","Weitere Schutzschichten":"لایه‌های محافظ دیگر","Eine sichere App prüft zusätzlich, ob Eingaben plausibel sind. Für einen Anzeigenamen kannst du Länge und erlaubte Form prüfen; die genaue Regel hängt vom Zweck ab. Eine Content-Security-Policy kann zusätzliche Schäden begrenzen, ersetzt aber keine sichere Ausgabe. Berechtigungen gehören auf den Server, falls ein Server beteiligt ist. Eine rein lokale Vorschau bietet keine Zugriffskontrolle für fremde Benutzer.":"یک اپ مطمئن علاوه بر آن بررسی می‌کند که آیا ورودی‌ها معقول‌اند. برای یک نام نمایشی می‌توانید طول و شکل مجاز را بررسی کنید؛ قاعدهٔ دقیق به هدف بستگی دارد. یک Content-Security-Policy می‌تواند آسیب‌های اضافی را محدود کند، اما جای نمایش مطمئن را نمی‌گیرد. اگر سروری در کار باشد، اجازه‌ها روی سرور جا دارند. یک پیش‌نمایش صرفاً محلی هیچ کنترول دسترسی برای کاربران بیگانه ندارد.","Eine sichere App prüft zusätzlich, ob Eingaben plausibel sind.":"یک اپ مطمئن علاوه بر آن بررسی می‌کند که آیا ورودی‌ها معقول‌اند.","Fremden Text als HTML einsetzen":"گذاشتن متن بیگانه به عنوان HTML","Falsch: `ausgabe.innerHTML = eingabe;` interpretiert HTML-Zeichen aus einer unbekannten Nachricht. Richtig: `ausgabe.textContent = eingabe;` zeigt die Nachricht als Text und verhindert diese Art von HTML-Ausführung.":"اشتباه: `ausgabe.innerHTML = eingabe;` نشانه‌های HTML یک پیام ناشناخته را تفسیر می‌کند. درست: `ausgabe.textContent = eingabe;` پیام را به شکل متن نشان می‌دهد و از این نوع اجرای HTML جلوگیری می‌کند.","Validierung als alleinigen Schutz betrachten":"بررسی ورودی را تنها محافظ دانستن","Falsch: `if (eingabe.length < 100) ausgabe.innerHTML = eingabe;` kann trotz kurzer Eingabe gefährliche HTML-Inhalte ausführen. Richtig: `if (eingabe.length < 100) ausgabe.textContent = eingabe;` kombiniert Plausibilitätsprüfung und sichere Ausgabe.":"اشتباه: `if (eingabe.length < 100) ausgabe.innerHTML = eingabe;` با وجود ورودی کوتاه می‌تواند محتوای خطرناک HTML را اجرا کند. درست: `if (eingabe.length < 100) ausgabe.textContent = eingabe;` بررسی معقول بودن و نمایش مطمئن را ترکیب می‌کند.","Setze „Eingaben prüfen und XSS vermeiden“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«بررسی ورودی‌ها و جلوگیری از XSS» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Setze einen Text mit spitzen Klammern ein und kontrolliere, dass keine HTML-Elemente entstehen.":"یک متن با قوس‌های زاویه‌دار بگذارید و بررسی کنید که هیچ عنصر HTML ساخته نشود.","Welche Eigenschaft zeigt fremde Texte ohne HTML-Interpretation?":"کدام ویژگی متن‌های بیگانه را بدون تفسیر HTML نشان می‌دهد؟","textContent setzt einen Textknoten statt HTML-Markup aus der Eingabe zu erzeugen.":"textContent به جای ساختن نشانه‌گذاری HTML از ورودی، یک گرهٔ متنی می‌گذارد.","Was bedeutet XSS?":"XSS یعنی چه؟","Ausführung eingeschleuster Inhalte im Seitenkontext":"اجرای محتوای واردشده در بافت صفحه","Eine Dateiendung":"یک پسوند فایل","Ein CSS-Raster":"یک شبکهٔ CSS","XSS kann entstehen, wenn Angreifer Inhalte im Kontext einer fremden Webseite ausführen.":"XSS وقتی پیدا می‌شود که مهاجمان محتوا را در بافت یک صفحهٔ ویب دیگر اجرا کنند.","Was ist bei fremden Daten richtig?":"با داده‌های بیگانه چه کاری درست است؟","Alles als HTML einfügen":"همه چیز را به عنوان HTML گذاشتن","Daten und HTML-Struktur trennen":"جدا کردن داده‌ها از ساختار HTML","Nur die Länge prüfen":"فقط بررسی طول","Unbekannte Eingaben bleiben Daten und werden nicht ungeprüft als HTML-Struktur interpretiert.":"ورودی‌های ناشناخته داده می‌مانند و بدون بررسی به عنوان ساختار HTML تفسیر نمی‌شوند.","Performance messen und DOM-Arbeit reduzieren":"اندازه‌گیری کارایی و کم کردن کار DOM","Eine Liste effizient und nachvollziehbar rendern":"یک لست را کارآمد و قابل پیگیری رسم کنید","Eine schnelle Oberfläche entsteht durch gezielte Messung und passende Datenstrukturen. Du lernst, unnötige Arbeit beim Rendern zu vermeiden.":"یک صفحهٔ سریع با اندازه‌گیری هدفمند و ساختارهای دادهٔ مناسب ساخته می‌شود. یاد می‌گیرید از کار غیرضروری هنگام رسم جلوگیری کنید.","Langsame Stellen finden":"پیدا کردن جاهای کند","Eine lange Teilnehmerliste kann beim Aufbau stocken. Bevor du etwas optimierst, miss die tatsächliche Dauer. `performance.now()` liefert eine hochauflösende Zeitangabe. Speichere die Zeit vor und nach dem Rendern und berechne die Differenz. Ein einzelner Messwert schwankt; wiederhole die Messung mit gleich großen Datenlisten. Ohne Messung ist eine vermeintliche Verbesserung nur eine Vermutung.":"یک لست طولانی شرکت‌کنندگان ممکن است هنگام ساخته شدن گیر کند. پیش از اینکه چیزی را بهینه کنید، مدت واقعی را اندازه بگیرید. `performance.now()` یک زمان با دقت بالا می‌دهد. زمان را پیش و بعد از رسم نگه دارید و تفاوت را حساب کنید. یک اندازه‌گیری تنها نوسان دارد؛ اندازه‌گیری را با لست‌های دادهٔ هم‌اندازه تکرار کنید. بدون اندازه‌گیری، یک بهبود ادعایی فقط یک حدس است.","Eine lange Teilnehmerliste kann beim Aufbau stocken.":"یک لست طولانی شرکت‌کنندگان ممکن است هنگام ساخته شدن گیر کند.","DOM-Arbeit bündeln":"یک‌جا کردن کار DOM","Wenn du hundertmal nacheinander sichtbare Elemente einfügst, muss der Browser viele Änderungen verwalten. Ein `DocumentFragment` ist wie ein Tablett, auf dem du alle Teller zuerst zusammenstellst. `document.createDocumentFragment()` erzeugt den unsichtbaren Behälter. Füge neue Listenelemente zunächst dort ein. Danach reicht ein gemeinsamer Schritt, um die fertige Gruppe anzuzeigen.":"اگر صد بار پشت سر هم عنصرهای قابل دید اضافه کنید، براوزر باید تغییرهای زیادی را مدیریت کند. یک `DocumentFragment` مثل یک سینی است که همهٔ بشقاب‌ها را اول روی آن می‌چینید. `document.createDocumentFragment()` ظرف نامرئی را می‌سازد. عنصرهای تازهٔ لست را اول آنجا اضافه کنید. بعد از آن یک قدم مشترک کافی است تا گروه آماده نشان داده شود.","Wenn du hundertmal nacheinander sichtbare Elemente einfügst, muss der Browser viele Änderungen verwalten.":"اگر صد بار پشت سر هم عنصرهای قابل دید اضافه کنید، براوزر باید تغییرهای زیادی را مدیریت کند.","Elemente sicher erzeugen":"ساختن مطمئن عنصرها","Ein Listeneintrag besteht aus einem echten `li`-Element und seinem Text. `document.createElement('li')` erzeugt die Struktur. `li.textContent = name` setzt den Namen, ohne HTML zu interpretieren. `fragment.appendChild(li)` sammelt den Eintrag. So verbindest du sichere Textausgabe und übersichtlichen DOM-Code. Verwende für jede Person ein neues Element.":"یک عنصر لست از یک عنصر واقعی `li` و متن آن ساخته شده است. `document.createElement('li')` ساختار را می‌سازد. `li.textContent = name` نام را می‌گذارد، بدون اینکه HTML را تفسیر کند. `fragment.appendChild(li)` عنصر را جمع می‌کند. به این ترتیب نمایش مطمئن متن و کد مرتب DOM را به هم وصل می‌کنید. برای هر شخص یک عنصر تازه به کار ببرید.","Ein Listeneintrag besteht aus einem echten `li`-Element und seinem Text.":"یک عنصر لست از یک عنصر واقعی `li` و متن آن ساخته شده است.","Nutzbarkeit vor Mikrooptimierung":"قابل استفاده بودن پیش از بهینه‌سازی‌های کوچک","Eine schnelle Liste ist wertlos, wenn sie auf dem Telefon nicht bedienbar ist. Prüfe mit Tastatur, Bildschirmleser und schmalem Bildschirm. Bei Tausenden Einträgen kann eine Seiteneinteilung sinnvoller sein als das gleichzeitige Rendern aller Zeilen. Lade nur die Daten, die du wirklich brauchst. Achte darauf, dass die Optimierung keine Inhalte versteckt oder die Reihenfolge unerwartet verändert.":"یک لست سریع بی‌ارزش است، اگر در تیلفون قابل استفاده نباشد. با کیبورد، صفحه‌خوان و صفحهٔ باریک بررسی کنید. با هزاران عنصر، صفحه‌بندی ممکن است معقول‌تر از رسم هم‌زمان همهٔ ردیف‌ها باشد. فقط داده‌هایی را بارگیری کنید که واقعاً لازم دارید. دقت کنید که بهینه‌سازی هیچ محتوایی را پنهان نکند یا ترتیب را غیرمنتظره تغییر ندهد.","Eine schnelle Liste ist wertlos, wenn sie auf dem Telefon nicht bedienbar ist.":"یک لست سریع بی‌ارزش است، اگر در تیلفون قابل استفاده نباشد.","Text als HTML zusammenbauen":"ساختن متن به عنوان HTML","Falsch: `liste.innerHTML += '<li>' + name + '</li>';` parst den gesamten HTML-Inhalt wiederholt und interpretiert fremde Namen als Markup. Richtig: `const li=document.createElement('li'); li.textContent=name; liste.appendChild(li);`.":"اشتباه: `liste.innerHTML += '<li>' + name + '</li>';` تمام محتوای HTML را بارها تجزیه می‌کند و نام‌های بیگانه را به عنوان نشانه‌گذاری تفسیر می‌کند. درست: `const li=document.createElement('li'); li.textContent=name; liste.appendChild(li);`.","Ohne Messung Geschwindigkeit behaupten":"ادعای سرعت بدون اندازه‌گیری","Falsch: `console.log('Jetzt doppelt so schnell');` beweist keine Verbesserung und liefert keine Laufzeit. Richtig: `const start=performance.now(); rendern(); console.log(performance.now()-start);` misst die tatsächlich benötigte Zeit.":"اشتباه: `console.log('Jetzt doppelt so schnell');` هیچ بهبودی را ثابت نمی‌کند و هیچ زمان اجرایی نمی‌دهد. درست: `const start=performance.now(); rendern(); console.log(performance.now()-start);` زمان واقعاً لازم را اندازه می‌گیرد.","Setze „Performance messen und DOM-Arbeit reduzieren“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«اندازه‌گیری کارایی و کم کردن کار DOM» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Erzeuge drei Listeneinträge im DocumentFragment und füge sie anschließend gemeinsam ein.":"سه عنصر لست را در DocumentFragment بسازید و بعد آن‌ها را یک‌جا اضافه کنید.","Was misst performance.now?":"performance.now چه چیزی را اندازه می‌گیرد؟","Zeitpunkte für Laufzeitmessungen":"لحظه‌هایی برای اندازه‌گیری زمان اجرا","Die Bildschirmbreite":"پهنای صفحه","Die Netzgeschwindigkeit direkt":"سرعت شبکه به‌طور مستقیم","performance.now liefert Zeitpunkte, deren Differenz die gemessene Dauer ergibt.":"performance.now لحظه‌هایی می‌دهد که تفاوتشان مدت اندازه‌گیری‌شده را نشان می‌دهد.","Wofür dient ein DocumentFragment?":"یک DocumentFragment برای چیست؟","Als Datenbank":"به عنوان پایگاه داده","Zum Sammeln von DOM-Knoten vor dem Einfügen":"برای جمع کردن گره‌های DOM پیش از اضافه کردن","Als HTTP-Server":"به عنوان سرور HTTP","Ein Fragment sammelt Listenelemente, bevor sie gemeinsam in die Seite eingefügt werden.":"یک Fragment عنصرهای لست را جمع می‌کند، پیش از اینکه یک‌جا به صفحه اضافه شوند.","Was bleibt bei einer Optimierung wichtig?":"در یک بهینه‌سازی چه چیزی مهم می‌ماند؟","Nur wenige Codezeilen":"فقط خط‌های کم کد","Ein bestimmtes Framework":"یک فریم‌ورک معین","Barrierefreiheit und korrekte Funktion":"دسترسی‌پذیری و کارکرد درست","Eine Verbesserung muss auch Tastaturbedienung und korrekte Inhalte erhalten.":"یک بهبود باید کار با کیبورد و محتوای درست را هم حفظ کند.","Automatische Tests für Funktionen":"آزمایش‌های خودکار برای تابع‌ها","Erwartete Ergebnisse und Grenzfälle prüfen":"نتیجه‌های مورد انتظار و حالت‌های مرزی را بررسی کنید","Tests machen Anforderungen überprüfbar und helfen bei späteren Änderungen. Du übst, Erfolgsfälle und Grenzfälle systematisch abzudecken.":"آزمایش‌ها خواسته‌ها را قابل بررسی می‌کنند و در تغییرهای بعدی کمک می‌کنند. تمرین می‌کنید حالت‌های موفق و مرزی را منظم پوشش دهید.","Verhalten vor dem Test beschreiben":"توصیف رفتار پیش از آزمایش","Eine Formularprüfung soll leere Eingaben ablehnen und sinnvolle Texte akzeptieren. Schreibe diese Regel zuerst in Alltagssprache auf. Ein Test ist wie eine Checkliste vor dem Öffnen eines Geschäfts: Er vergleicht eine konkrete Eingabe mit einem erwarteten Ergebnis. Prüfe nicht nur den Normalfall, sondern auch Leerzeichen und unerwartete Datentypen. So werden Anforderungen nachvollziehbar.":"یک بررسی فورم باید ورودی‌های خالی را رد کند و متن‌های معقول را بپذیرد. این قاعده را اول به زبان روزمره بنویسید. یک آزمایش مثل یک چک‌لست پیش از باز کردن یک دکان است: یک ورودی مشخص را با یک نتیجهٔ مورد انتظار مقایسه می‌کند. فقط حالت عادی را بررسی نکنید، بلکه فاصله‌ها و نوع‌های غیرمنتظرهٔ داده را هم. به این ترتیب خواسته‌ها قابل پیگیری می‌شوند.","Eine Formularprüfung soll leere Eingaben ablehnen und sinnvolle Texte akzeptieren.":"یک بررسی فورم باید ورودی‌های خالی را رد کند و متن‌های معقول را بپذیرد.","Eine reine Funktion bauen":"ساختن یک تابع خالص","`istGueltig` nimmt einen Wert entgegen und liefert true oder false. `typeof text === 'string'` verhindert, dass die Funktion bei Zahlen unbedacht trim aufruft. `text.trim().length > 0` entfernt gedanklich Rand-Leerzeichen und prüft, ob etwas übrig bleibt. Weil die Funktion keine Webseite verändert, kann ein Test sie direkt aufrufen. Die gleiche Eingabe erzeugt immer das gleiche Ergebnis.":"`istGueltig` یک مقدار می‌گیرد و true یا false می‌دهد. `typeof text === 'string'` جلوگیری می‌کند که تابع در عددها بی‌دقت trim را صدا بزند. `text.trim().length > 0` فاصله‌های دو طرف را کنار می‌گذارد و بررسی می‌کند که آیا چیزی باقی می‌ماند. چون تابع هیچ صفحهٔ ویبی را تغییر نمی‌دهد، یک آزمایش می‌تواند آن را مستقیم صدا بزند. ورودی یکسان همیشه نتیجهٔ یکسان می‌دهد.","`istGueltig` nimmt einen Wert entgegen und liefert true oder false.":"`istGueltig` یک مقدار می‌گیرد و true یا false می‌دهد.","Mit assert vergleichen":"مقایسه با assert","Ein Test prüft die Antwort wie eine Lehrkraft eine Musterlösung. `console.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein')` meldet eine fehlgeschlagene Erwartung in der Konsole. Der zweite Test erwartet false für reine Leerzeichen. `console.assert` ist für eine erste Browserübung geeignet, setzt aber keinen verlässlichen CI-Exitcode. In Node.js nutzt du später `node:test` und `assert` für echte automatisierte Testläufe.":"یک آزمایش جواب را مثل معلمی که با پاسخ نمونه مقایسه می‌کند بررسی می‌کند. `console.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein')` یک انتظار ناکام را در کنسول گزارش می‌دهد. آزمایش دوم برای فقط فاصله‌ها false انتظار دارد. `console.assert` برای یک تمرین اول در براوزر مناسب است، اما یک کد خروج مطمئن CI نمی‌دهد. در Node.js بعداً `node:test` و `assert` را برای اجراهای واقعی خودکار آزمایش به کار می‌برید.","Ein Test prüft die Antwort wie eine Lehrkraft eine Musterlösung.":"یک آزمایش جواب را مثل معلمی که با پاسخ نمونه مقایسه می‌کند بررسی می‌کند.","Fehler gezielt nachstellen":"بازسازی هدفمند خطا","Ändere absichtlich die Funktion so, dass Leerzeichen als gültig gelten. Der Negativtest muss nun fehlschlagen; sonst prüft er nicht die gewünschte Regel. Stelle danach die korrekte Funktion wieder her. Führe Tests nach jeder Änderung aus, besonders wenn mehrere Funktionen voneinander abhängen. Ein grüner Test beweist nur das geprüfte Verhalten, nicht die vollständige Fehlerfreiheit.":"عمداً تابع را طوری تغییر دهید که فاصله‌ها معتبر حساب شوند. اکنون آزمایش منفی باید ناکام شود؛ در غیر آن قاعدهٔ خواسته‌شده را بررسی نمی‌کند. بعد تابع درست را دوباره برگردانید. آزمایش‌ها را بعد از هر تغییر اجرا کنید، به‌خصوص وقتی چند تابع به هم وابسته‌اند. یک آزمایش سبز فقط رفتار بررسی‌شده را ثابت می‌کند، نه بی‌خطایی کامل را.","Ändere absichtlich die Funktion so, dass Leerzeichen als gültig gelten.":"عمداً تابع را طوری تغییر دهید که فاصله‌ها معتبر حساب شوند.","Nur den Erfolgsfall prüfen":"فقط بررسی حالت موفق","Falsch: `console.assert(istGueltig('Hallo'));` prüft nicht, ob Leerzeichen fälschlich akzeptiert werden. Richtig: `console.assert(istGueltig('   ') === false);` ergänzt einen wichtigen Grenzfall.":"اشتباه: `console.assert(istGueltig('Hallo'));` بررسی نمی‌کند که آیا فاصله‌ها به اشتباه پذیرفته می‌شوند. درست: `console.assert(istGueltig('   ') === false);` یک حالت مرزی مهم را اضافه می‌کند.","Konsole mit CI verwechseln":"اشتباه گرفتن کنسول با CI","Falsch: `console.assert(false);` garantiert keinen fehlgeschlagenen Node-Testlauf. Richtig: `const assert=require('node:assert/strict'); assert.equal(2+2,4);` in einer Node-Testdatei verwendet eine echte Assertion.":"اشتباه: `console.assert(false);` یک اجرای ناکام آزمایش Node را تضمین نمی‌کند. درست: `const assert=require('node:assert/strict'); assert.equal(2+2,4);` در یک فایل آزمایش Node یک Assertion واقعی به کار می‌برد.","Setze „Automatische Tests für Funktionen“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«آزمایش‌های خودکار برای تابع‌ها» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Teste istGueltig mit Leerzeichen und einem echten Text, bevor du den DOM-Code änderst.":"istGueltig را پیش از تغییر کد DOM با فاصله‌ها و یک متن واقعی آزمایش کنید.","Was ist ein Negativtest?":"آزمایش منفی چیست؟","Ein dunkles Theme":"یک تم تاریک","Eine entfernte Datei":"یک فایل پاک‌شده","Ein Test mit einer bewusst ungültigen Eingabe":"آزمایشی با یک ورودی عمداً نامعتبر","Eine ungültige Eingabe wie Leerzeichen gehört ausdrücklich in die Negativtests.":"یک ورودی نامعتبر مثل فاصله‌ها صریحاً جزو آزمایش‌های منفی است.","Warum sind reine Funktionen gut testbar?":"چرا تابع‌های خالص خوب آزمایش می‌شوند؟","Sie laden automatisch Webseiten":"خودکار صفحه‌های ویب را بارگیری می‌کنند","Sie haben keine versteckten DOM-Seiteneffekte":"اثر جانبی پنهان روی DOM ندارند","Sie brauchen nie Parameter":"هرگز به پارامتر نیاز ندارند","Reine Funktionen liefern für dieselben Argumente denselben Wert ohne DOM-Seiteneffekte.":"تابع‌های خالص برای آرگومان‌های یکسان مقدار یکسان می‌دهند، بدون اثر جانبی روی DOM.","Was sollte bei einem absichtlich eingebauten Fehler passieren?":"با یک خطای عمداً گذاشته‌شده چه باید شود؟","Der passende Test schlägt fehl":"آزمایش مربوط ناکام می‌شود","Die Tests bleiben grün":"آزمایش‌ها سبز می‌مانند","Die Seite wird gelöscht":"صفحه پاک می‌شود","Ein absichtlich eingebauter Defekt muss vom passenden Test erkannt werden.":"یک نقص عمداً گذاشته‌شده باید توسط آزمایش مربوط شناخته شود.","Git: Änderungen nachvollziehbar sichern":"Git: تغییرها را قابل پیگیری ذخیره کنید","Status, Stage und Commit unterscheiden":"Status، Stage و Commit را از هم جدا کنید","Versionskontrolle bewahrt nachvollziehbare Arbeitsschritte statt unübersichtlicher Dateikopien. Du lernst, Änderungen bewusst für einen Commit auszuwählen.":"کنترول نسخه قدم‌های کاری قابل پیگیری را نگه می‌دارد، به جای کاپی‌های نامرتب فایل. یاد می‌گیرید تغییرها را آگاهانه برای یک Commit انتخاب کنید.","Arbeitsverzeichnis verstehen":"فهمیدن پوشهٔ کاری","Beim Schreiben eines Buchs sind nicht alle Änderungen sofort Teil einer veröffentlichten Ausgabe. Git unterscheidet die aktuellen Dateien im Arbeitsverzeichnis von gespeicherten Versionsständen. `git status` zeigt, welche Dateien verändert, neu oder zum Commit vorgemerkt sind. Lies diese Anzeige, bevor du einen Commit erstellst. Prüfe, ob versehentlich persönliche Daten oder große Dateien auftauchen.":"هنگام نوشتن یک کتاب، همهٔ تغییرها فوراً بخشی از یک چاپ منتشرشده نیستند. Git فایل‌های فعلی در پوشهٔ کاری را از نسخه‌های ذخیره‌شده جدا می‌کند. `git status` نشان می‌دهد کدام فایل‌ها تغییر کرده‌اند، تازه‌اند یا برای Commit علامت خورده‌اند. پیش از ساختن یک Commit این نمایش را بخوانید. بررسی کنید که آیا به اشتباه داده‌های شخصی یا فایل‌های بزرگ دیده می‌شوند.","Beim Schreiben eines Buchs sind nicht alle Änderungen sofort Teil einer veröffentlichten Ausgabe.":"هنگام نوشتن یک کتاب، همهٔ تغییرها فوراً بخشی از یک چاپ منتشرشده نیستند.","Änderungen gezielt vormerken":"علامت زدن هدفمند تغییرها","Mit `git add mein-sd-hub/app.js` legst du genau diese Datei in die Staging Area. Das ist wie die Auswahl der Seiten, die in die nächste Druckauflage sollen. `git add .` würde alle Änderungen im aktuellen Verzeichnis vormerken und kann unerwünschte Dateien erfassen. Kontrolliere deshalb danach erneut `git status`. Ein Commit sollte nur logisch zusammengehörige Änderungen enthalten.":"با `git add mein-sd-hub/app.js` دقیقاً همین فایل را در Staging Area می‌گذارید. این مثل انتخاب صفحه‌هایی است که باید در چاپ بعدی بروند. `git add .` همهٔ تغییرهای پوشهٔ فعلی را علامت می‌زد و ممکن است فایل‌های ناخواسته را هم بگیرد. به همین دلیل بعد از آن دوباره `git status` را بررسی کنید. یک Commit فقط باید تغییرهایی را داشته باشد که منطقاً به هم مربوط‌اند.","Mit `git add mein-sd-hub/app.js` legst du genau diese Datei in die Staging Area.":"با `git add mein-sd-hub/app.js` دقیقاً همین فایل را در Staging Area می‌گذارید.","Einen Commit erstellen":"ساختن یک Commit","Ein Commit ist ein beschrifteter Schnappschuss der vorgemerkten Änderungen. `git commit -m \"Anzeige verbessern\"` erstellt ihn mit einer kurzen Beschreibung. Die Nachricht erklärt, was sich geändert hat, nicht nur dass irgendetwas passiert ist. Mit `git log --oneline` kannst du die Geschichte später nachverfolgen. Ein lokaler Commit ist noch nicht automatisch auf GitHub verfügbar.":"یک Commit عکس فوری برچسب‌داری از تغییرهای علامت‌خورده است. `git commit -m \"Anzeige verbessern\"` آن را با یک توضیح کوتاه می‌سازد. پیام توضیح می‌دهد که چه چیزی تغییر کرده، نه فقط اینکه چیزی اتفاق افتاده است. با `git log --oneline` می‌توانید تاریخچه را بعداً پیگیری کنید. یک Commit محلی هنوز خودکار در GitHub در دسترس نیست.","Ein Commit ist ein beschrifteter Schnappschuss der vorgemerkten Änderungen.":"یک Commit عکس فوری برچسب‌داری از تغییرهای علامت‌خورده است.","Sicher mit Fehlern umgehen":"برخورد مطمئن با خطاها","Wenn eine Änderung misslingt, solltest du wissen, ob sie bereits gestaged oder committed wurde. `git diff` zeigt ungestagte Unterschiede; `git diff --staged` zeigt die Auswahl für den nächsten Commit. Lies die Unterschiede vor dem Speichern. Verwende keine destruktiven Rücksetzbefehle, ohne ihre Folgen zu verstehen. Halte geheime Schlüssel grundsätzlich außerhalb des Repositorys.":"اگر یک تغییر ناکام شود، باید بدانید که آیا از قبل Stage یا Commit شده است. `git diff` تفاوت‌های Stage‌نشده را نشان می‌دهد؛ `git diff --staged` انتخاب برای Commit بعدی را نشان می‌دهد. تفاوت‌ها را پیش از ذخیره بخوانید. دستورهای ویرانگر بازگشت را بدون فهمیدن پیامدهایشان به کار نبرید. کلیدهای محرمانه را همیشه بیرون از مخزن نگه دارید.","Wenn eine Änderung misslingt, solltest du wissen, ob sie bereits gestaged oder committed wurde.":"اگر یک تغییر ناکام شود، باید بدانید که آیا از قبل Stage یا Commit شده است.","Alle Dateien blind vormerken":"علامت زدن کورکورانهٔ همهٔ فایل‌ها","Falsch: `git add .` ohne Kontrolle kann versehentlich eine Datei mit Zugangsdaten aufnehmen. Richtig: `git status` prüfen und `git add mein-sd-hub/app.js` für gezielt ausgewählte Änderungen nutzen.":"اشتباه: `git add .` بدون بررسی ممکن است به اشتباه فایلی با معلومات ورود را بگیرد. درست: `git status` را بررسی کنید و `git add mein-sd-hub/app.js` را برای تغییرهای هدفمند انتخاب‌شده به کار ببرید.","Commit mit Veröffentlichung verwechseln":"اشتباه گرفتن Commit با نشر","Falsch: `git commit -m 'Fertig'` macht den Stand sofort auf GitHub sichtbar. Richtig: Nach dem lokalen Commit braucht ein verbundenes Remote normalerweise `git push`, bevor andere den Commit sehen.":"اشتباه: `git commit -m 'Fertig'` وضعیت را فوراً در GitHub قابل دید می‌کند. درست: بعد از Commit محلی، یک Remote وصل‌شده معمولاً به `git push` نیاز دارد، پیش از اینکه دیگران Commit را ببینند.","Setze „Git: Änderungen nachvollziehbar sichern“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«Git: تغییرها را قابل پیگیری ذخیره کنید» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Prüfe mit git status genau, welche Datei für deinen nächsten Commit vorgemerkt ist.":"با git status دقیق بررسی کنید که کدام فایل برای Commit بعدی شما علامت خورده است.","Was zeigt git status?":"git status چه نشان می‌دهد؟","Die Browserauflösung":"وضوح براوزر","Den Zustand der Dateien":"وضعیت فایل‌ها","Das CSS-Layout":"چیدمان CSS","git status zeigt, welche Änderungen noch offen oder vorgemerkt sind.":"git status نشان می‌دهد کدام تغییرها هنوز باز یا علامت‌خورده‌اند.","Was macht git add?":"git add چه کار می‌کند؟","Merkt Änderungen für einen Commit vor":"تغییرها را برای یک Commit علامت می‌زند","Löscht die Historie":"تاریخچه را پاک می‌کند","Veröffentlicht eine Website":"یک ویب‌سایت را منتشر می‌کند","git add wählt Dateien für den nächsten Commit aus, veröffentlicht sie aber nicht.":"git add فایل‌ها را برای Commit بعدی انتخاب می‌کند، اما آن‌ها را منتشر نمی‌کند.","Was beschreibt eine gute Commit-Nachricht?":"یک پیام Commit خوب چه چیزی را توصیف می‌کند؟","Nur das Datum":"فقط تاریخ","Nur den Benutzernamen":"فقط نام کاربر","Den Zweck der Änderung":"هدف تغییر","Eine Commit-Nachricht soll erklären, welche zusammengehörige Änderung gespeichert wurde.":"یک پیام Commit باید توضیح دهد که کدام تغییر مربوط به هم ذخیره شده است.","Branches und Pull Requests auf GitHub":"Branchها و Pull Requestها در GitHub","Änderungen getrennt prüfen und zusammenführen":"تغییرها را جدا بررسی کنید و یکی کنید","Zusammenarbeit an Software braucht getrennte Änderungen und klare Freigaben. Du lernst, Branches und Pull Requests verantwortungsvoll zu nutzen.":"همکاری روی نرم‌افزار به تغییرهای جدا و تأییدهای روشن نیاز دارد. یاد می‌گیرید Branchها و Pull Requestها را مسئولانه به کار ببرید.","Eine Aufgabe isolieren":"جدا کردن یک کار","Wenn zwei Personen gleichzeitig an einer Website arbeiten, sollten sie nicht dieselben unfertigen Änderungen direkt in main speichern. Ein Branch ist wie ein eigener Arbeitstisch für ein Vorhaben. `git switch -c feature/lesbarkeit` erstellt und aktiviert einen neuen Branch. Er beginnt am aktuellen Commit. Prüfe vorher, ob dein lokaler main mit dem Remote-Stand übereinstimmt.":"وقتی دو نفر هم‌زمان روی یک ویب‌سایت کار می‌کنند، نباید تغییرهای ناتمام را مستقیم در main ذخیره کنند. یک Branch مثل یک میز کار جداگانه برای یک کار است. `git switch -c feature/lesbarkeit` یک Branch تازه می‌سازد و فعال می‌کند. از Commit فعلی شروع می‌شود. پیش از آن بررسی کنید که آیا main محلی شما با وضعیت Remote یکی است.","Wenn zwei Personen gleichzeitig an einer Website arbeiten, sollten sie nicht dieselben unfertigen Änderungen direkt in main speichern.":"وقتی دو نفر هم‌زمان روی یک ویب‌سایت کار می‌کنند، نباید تغییرهای ناتمام را مستقیم در main ذخیره کنند.","Den Branch veröffentlichen":"منتشر کردن Branch","Andere können deine Arbeit erst auf GitHub sehen, wenn du den Branch hochlädst. `git push -u origin feature/lesbarkeit` legt den Branch beim Remote an und verbindet ihn mit dem lokalen. Danach kannst du die Unterschiede online ansehen. Veröffentliche niemals Passwörter, Tokens oder persönliche Daten. Ein Push ist noch kein Merge nach main.":"دیگران فقط وقتی می‌توانند کار شما را در GitHub ببینند که Branch را بالا بفرستید. `git push -u origin feature/lesbarkeit` ‏Branch را در Remote می‌سازد و آن را با Branch محلی وصل می‌کند. بعد از آن می‌توانید تفاوت‌ها را آنلاین ببینید. هرگز رمز، توکن یا داده‌های شخصی را منتشر نکنید. یک Push هنوز Merge به main نیست.","Andere können deine Arbeit erst auf GitHub sehen, wenn du den Branch hochlädst.":"دیگران فقط وقتی می‌توانند کار شما را در GitHub ببینند که Branch را بالا بفرستید.","Pull Request vorbereiten":"آماده کردن Pull Request","Ein Pull Request ist eine Bitte, die Änderungen eines Branches in einen Zielbranch zu übernehmen. Beschreibe, was sich geändert hat, welche Tests liefen und welche Risiken bestehen. Ein Draft-PR signalisiert, dass noch Arbeit aussteht. Bitte bei wichtigen Änderungen um Review. Prüfe im Diff, ob nur die beabsichtigten Dateien geändert wurden.":"یک Pull Request درخواستی است برای اینکه تغییرهای یک Branch در یک Branch هدف پذیرفته شوند. توضیح دهید که چه چیزی تغییر کرده، کدام آزمایش‌ها اجرا شدند و چه خطرهایی هست. یک Draft-PR نشان می‌دهد که هنوز کار باقی است. برای تغییرهای مهم درخواست بازبینی کنید. در Diff بررسی کنید که آیا فقط فایل‌های مورد نظر تغییر کرده‌اند.","Ein Pull Request ist eine Bitte, die Änderungen eines Branches in einen Zielbranch zu übernehmen.":"یک Pull Request درخواستی است برای اینکه تغییرهای یک Branch در یک Branch هدف پذیرفته شوند.","Erst nach Prüfungen mergen":"Merge فقط بعد از بررسی‌ها","Ein grüner Test ist wie eine bestandene Qualitätskontrolle vor der Auslieferung. Warte auf die erforderlichen CI-Prüfungen und lies bei Fehlern die Logs. Aktualisiere den Branch, falls main inzwischen weiterentwickelt wurde. Beim Merge-Commit bleibt die PR-Geschichte nachvollziehbar. Kontrolliere anschließend erneut die Tests auf main, denn die Kombination mehrerer Änderungen kann neue Fehler auslösen.":"یک آزمایش سبز مثل یک کنترول کیفیت قبول‌شده پیش از تحویل است. منتظر بررسی‌های لازم CI بمانید و در صورت خطا لاگ‌ها را بخوانید. اگر main در این میان پیش رفته باشد، Branch را به‌روز کنید. با Merge-Commit تاریخچهٔ PR قابل پیگیری می‌ماند. بعد از آن آزمایش‌ها را روی main دوباره بررسی کنید، چون ترکیب چند تغییر ممکن است خطاهای تازه ایجاد کند.","Ein grüner Test ist wie eine bestandene Qualitätskontrolle vor der Auslieferung.":"یک آزمایش سبز مثل یک کنترول کیفیت قبول‌شده پیش از تحویل است.","Direkt auf main experimentieren":"آزمایش مستقیم روی main","Falsch: Neue ungetestete Funktionen unmittelbar nach main pushen kann die öffentliche Website beeinträchtigen. Richtig: `git switch -c feature/lesbarkeit` verwenden, Tests ausführen und einen Pull Request zur Prüfung erstellen.":"اشتباه: فرستادن مستقیم کارکردهای تازه و آزمایش‌نشده به main ممکن است به ویب‌سایت عمومی آسیب بزند. درست: `git switch -c feature/lesbarkeit` را به کار ببرید، آزمایش‌ها را اجرا کنید و یک Pull Request برای بررسی بسازید.","Rote CI ignorieren":"نادیده گرفتن CI سرخ","Falsch: Einen Pull Request trotz fehlgeschlagener Tests mergen und die Ursache später suchen. Richtig: Fehlerlogs lesen, die Ursache beheben und auf einen erfolgreichen erneuten Testlauf warten.":"اشتباه: یک Pull Request را با وجود آزمایش‌های ناکام Merge کنید و علت را بعداً جستجو کنید. درست: لاگ‌های خطا را بخوانید، علت را رفع کنید و منتظر یک اجرای دوبارهٔ موفق آزمایش بمانید.","Setze „Branches und Pull Requests auf GitHub“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«Branchها و Pull Requestها در GitHub» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Erstelle einen Feature-Branch und kontrolliere im Pull-Request-Diff ausschließlich die gewünschten Dateien.":"یک Feature-Branch بسازید و در Diff ‏Pull Request فقط فایل‌های خواسته‌شده را بررسی کنید.","Wozu dient ein Feature-Branch?":"یک Feature-Branch برای چیست؟","Zum isolierten Arbeiten":"برای کار جداگانه","Zum Löschen von Tests":"برای پاک کردن آزمایش‌ها","Zum Erstellen von HTML":"برای ساختن HTML","Ein Feature-Branch hält unfertige Änderungen von der stabilen Hauptentwicklung getrennt.":"یک Feature-Branch تغییرهای ناتمام را از توسعهٔ اصلی پایدار جدا نگه می‌دارد.","Was ist ein Pull Request?":"Pull Request چیست؟","Ein Browser-Cache":"یک حافظهٔ موقت براوزر","Eine Python-Bibliothek":"یک کتابخانهٔ پایتون","Ein Vorschlag zum Zusammenführen von Änderungen":"پیشنهادی برای یکی کردن تغییرها","Ein Pull Request zeigt den vorgeschlagenen Unterschied zwischen Arbeits- und Zielbranch.":"یک Pull Request تفاوت پیشنهادی بین Branch کاری و Branch هدف را نشان می‌دهد.","Wann sollte gemergt werden?":"چه وقت باید Merge کرد؟","Vor dem Schreiben der Tests":"پیش از نوشتن آزمایش‌ها","Nach Review und erfolgreichen erforderlichen Prüfungen":"بعد از بازبینی و بررسی‌های لازم موفق","Sobald eine Datei existiert":"همین که یک فایل وجود داشته باشد","Vor dem Merge müssen Review und erforderliche CI-Prüfungen erfolgreich sein.":"پیش از Merge، بازبینی و بررسی‌های لازم CI باید موفق باشند.","Webseite sicher veröffentlichen":"نشر مطمئن یک ویب‌سایت","Build, Pfade und Deployment überprüfen":"Build، مسیرها و Deployment را بررسی کنید","Die Veröffentlichung einer Webseite ist ein eigener Qualitätsschritt. Du prüfst Ressourcen, Sicherheit und den tatsächlichen Deployment-Status.":"نشر یک ویب‌سایت یک قدم جداگانهٔ کیفیت است. منابع، امنیت و وضعیت واقعی Deployment را بررسی می‌کنید.","Eine veröffentlichbare Version prüfen":"بررسی یک نسخهٔ قابل نشر","Eine Webseite funktioniert auf dem eigenen Rechner, aber das garantiert noch keinen erfolgreichen öffentlichen Aufruf. Überprüfe die Startseite, alle verlinkten Dateien und die mobile Ansicht. Achte auf Groß- und Kleinschreibung in Dateinamen; Webserver unterscheiden sie häufig. Öffne die Browserkonsole und suche nach Ladefehlern. Ein einfacher Test auf localhost ersetzt keine Kontrolle der tatsächlichen Internetadresse.":"یک ویب‌سایت روی کمپیوتر خودتان کار می‌کند، اما این هنوز باز شدن موفق عمومی را تضمین نمی‌کند. صفحهٔ اول، همهٔ فایل‌های لینک‌شده و نمای موبایل را بررسی کنید. به حروف بزرگ و کوچک در نام فایل‌ها توجه کنید؛ سرورهای ویب اغلب آن‌ها را از هم جدا می‌کنند. کنسول براوزر را باز کنید و دنبال خطاهای بارگیری بگردید. یک آزمایش ساده روی localhost جای بررسی آدرس واقعی انترنتی را نمی‌گیرد.","Eine Webseite funktioniert auf dem eigenen Rechner, aber das garantiert noch keinen erfolgreichen öffentlichen Aufruf.":"یک ویب‌سایت روی کمپیوتر خودتان کار می‌کند، اما این هنوز باز شدن موفق عمومی را تضمین نمی‌کند.","Dateipfade verstehen":"فهمیدن مسیرهای فایل","Ein Bildpfad `./bilder/logo.svg` ist relativ zur aktuellen Datei. Ein Pfad `/bilder/logo.svg` beginnt dagegen an der Wurzel der Website. Wenn ein Projekt unter einem Unterordner veröffentlicht wird, kann ein falscher absoluter Pfad zu 404 führen. Plane deshalb die Zieladresse frühzeitig ein. Prüfe CSS-, JavaScript- und Bilddateien auf der veröffentlichten Seite.":"یک مسیر عکس `./bilder/logo.svg` نسبت به فایل فعلی است. اما یک مسیر `/bilder/logo.svg` از ریشهٔ ویب‌سایت شروع می‌شود. اگر یک پروژه زیر یک پوشهٔ فرعی منتشر شود، یک مسیر مطلق اشتباه ممکن است به 404 بینجامد. به همین دلیل آدرس هدف را از اول در نظر بگیرید. فایل‌های CSS، JavaScript و عکس را روی صفحهٔ منتشرشده بررسی کنید.","Ein Bildpfad `./bilder/logo.svg` ist relativ zur aktuellen Datei.":"یک مسیر عکس `./bilder/logo.svg` نسبت به فایل فعلی است.","Deployment beobachten":"دیده‌بانی Deployment","Ein Hosting-Dienst kann aus dem Repository eine neue Website-Version bereitstellen. GitHub Pages zeigt einen eigenen Build- und Deployment-Status. Ein erfolgreicher Code-Test ist nicht automatisch ein erfolgreicher Pages-Deploy. Warte auf die Abschlussmeldung und kontrolliere die tatsächlich ausgelieferte URL. Bei einem Fehler solltest du das Deployment-Log lesen und die Ursache beheben.":"یک سرویس میزبانی می‌تواند از مخزن یک نسخهٔ تازهٔ ویب‌سایت فراهم کند. GitHub Pages یک وضعیت جداگانهٔ Build و Deployment نشان می‌دهد. یک آزمایش موفق کد خودکار یک Deploy موفق Pages نیست. منتظر پیام پایان بمانید و URL واقعاً تحویل‌داده‌شده را بررسی کنید. در صورت خطا باید لاگ Deployment را بخوانید و علت را رفع کنید.","Ein Hosting-Dienst kann aus dem Repository eine neue Website-Version bereitstellen.":"یک سرویس میزبانی می‌تواند از مخزن یک نسخهٔ تازهٔ ویب‌سایت فراهم کند.","Sicherheit und Aktualität":"امنیت و به‌روز بودن","Eine öffentliche Website sollte über HTTPS erreichbar sein. Veröffentliche keine privaten Zugangsdaten im JavaScript oder Repository. Prüfe, ob Formulare verständliche Fehlermeldungen anzeigen und die Navigation mit der Tastatur funktioniert. Nach der Veröffentlichung können alte Dateien im Browsercache liegen; kontrolliere daher auch die Aktualisierung. Halte eine bekannte funktionierende Version für einen Rückweg bereit.":"یک ویب‌سایت عمومی باید از راه HTTPS در دسترس باشد. هیچ معلومات ورود خصوصی را در JavaScript یا مخزن منتشر نکنید. بررسی کنید که آیا فورم‌ها پیام‌های خطای قابل فهم نشان می‌دهند و منو با کیبورد کار می‌کند. بعد از نشر ممکن است فایل‌های قدیمی در حافظهٔ موقت براوزر باشند؛ به همین دلیل به‌روز شدن را هم بررسی کنید. یک نسخهٔ شناخته‌شدهٔ کارکننده را برای راه بازگشت آماده نگه دارید.","Eine öffentliche Website sollte über HTTPS erreichbar sein.":"یک ویب‌سایت عمومی باید از راه HTTPS در دسترس باشد.","Nur lokalen Aufruf prüfen":"فقط بررسی باز شدن محلی","Falsch: `http://localhost:8000` funktioniert, also ist die Seite automatisch öffentlich erreichbar. Richtig: Nach dem Deployment die echte HTTPS-Adresse öffnen und alle Ressourcen sowie Browserfehler prüfen.":"اشتباه: `http://localhost:8000` کار می‌کند، پس صفحه خودکار عمومی در دسترس است. درست: بعد از Deployment آدرس واقعی HTTPS را باز کنید و همهٔ منابع و خطاهای براوزر را بررسی کنید.","Tests mit Deployment verwechseln":"اشتباه گرفتن آزمایش‌ها با Deployment","Falsch: Eine grüne Unit-Test-Action bedeutet, dass GitHub Pages die neue Seite bereits ausliefert. Richtig: Den separaten Pages-Build und die erfolgreiche Bereitstellung kontrollieren.":"اشتباه: یک Action سبز آزمایش واحد یعنی GitHub Pages صفحهٔ تازه را از قبل تحویل می‌دهد. درست: Build جداگانهٔ Pages و فراهم شدن موفق را بررسی کنید.","Setze „Webseite sicher veröffentlichen“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«نشر مطمئن یک ویب‌سایت» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Kontrolliere nach dem Deployment die echte HTTPS-Adresse und die Ladefehler der Browserkonsole.":"بعد از Deployment آدرس واقعی HTTPS و خطاهای بارگیری کنسول براوزر را بررسی کنید.","Was ist nach dem Deployment zu prüfen?":"بعد از Deployment چه چیزی را باید بررسی کرد؟","Nur der Editor":"فقط ویرایشگر","Nur die Commit-Nachricht":"فقط پیام Commit","Die echte öffentliche URL":"URL واقعی عمومی","Die öffentliche URL beweist, ob die veröffentlichte Version tatsächlich erreichbar ist.":"URL عمومی ثابت می‌کند که آیا نسخهٔ منتشرشده واقعاً در دسترس است.","Was bedeutet ein 404 bei einer Ressource?":"404 برای یک منبع یعنی چه؟","Ein erfolgreicher Test":"یک آزمایش موفق","Ein gültiges CSS-Layout":"یک چیدمان معتبر CSS","Die Datei wurde unter diesem Pfad nicht gefunden":"فایل زیر این مسیر پیدا نشد","Ein HTTP-Status 404 bedeutet, dass die angeforderte Ressource am Pfad fehlt.":"وضعیت HTTP ‏404 یعنی منبع خواسته‌شده در آن مسیر نیست.","Was ist für öffentliche Webseiten wichtig?":"برای ویب‌سایت‌های عمومی چه چیزی مهم است؟","Passwörter im JavaScript":"رمزها در JavaScript","HTTPS und keine veröffentlichten Geheimnisse":"HTTPS و هیچ راز منتشرشده","Nur Desktop-Bedienung":"فقط کار با کمپیوتر رومیزی","HTTPS und der Schutz geheimer Daten gehören zur Freigabe einer öffentlichen Seite.":"HTTPS و محافظت از داده‌های محرمانه بخشی از آزاد کردن یک صفحهٔ عمومی‌اند.","Abschlussprojekt: barrierefreie Aufgaben-App":"پروژهٔ پایانی: اپ کارهای دسترس‌پذیر","Sichere Ausgabe, Testbarkeit und Bedienbarkeit kombinieren":"نمایش مطمئن، قابل آزمایش بودن و قابل استفاده بودن را ترکیب کنید","Ein Abschlussprojekt zeigt, ob die einzelnen Techniken zusammen funktionieren. Du baust eine bedienbare Aufgabenliste mit sicherer Textausgabe.":"یک پروژهٔ پایانی نشان می‌دهد که آیا تکنیک‌های جداگانه با هم کار می‌کنند. یک لست کارهای قابل استفاده با نمایش مطمئن متن می‌سازید.","Anforderungen konkretisieren":"مشخص کردن خواسته‌ها","Deine Aufgaben-App soll Einträge aufnehmen, leere Texte ablehnen und die Aufgaben als echte Liste anzeigen. Schreibe diese drei Regeln auf, bevor du programmierst. Eine gute App lässt sich mit Tastatur und Smartphone bedienen. Das Eingabefeld braucht eine sichtbare Beschriftung, der Knopf einen verständlichen Namen. Speichere zunächst keine sensiblen Daten; für das Abschlussprojekt genügt eine lokale Liste.":"اپ کارهای شما باید عنصرها را بپذیرد، متن‌های خالی را رد کند و کارها را به شکل یک لست واقعی نشان دهد. این سه قاعده را پیش از برنامه‌نویسی بنویسید. یک اپ خوب با کیبورد و موبایل قابل استفاده است. خانهٔ ورودی به یک برچسب قابل دید و دکمه به یک نام قابل فهم نیاز دارد. اول هیچ دادهٔ حساسی ذخیره نکنید؛ برای پروژهٔ پایانی یک لست محلی کافی است.","Deine Aufgaben-App soll Einträge aufnehmen, leere Texte ablehnen und die Aufgaben als echte Liste anzeigen.":"اپ کارهای شما باید عنصرها را بپذیرد، متن‌های خالی را رد کند و کارها را به شکل یک لست واقعی نشان دهد.","Eingabe von Darstellung trennen":"جدا کردن ورودی از نمایش","`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` erzeugt ein Datenobjekt und ist ohne Browser testbar. Die Klickfunktion liest dagegen den aktuellen Wert aus dem Eingabefeld. `if (!text) return;` verhindert einen leeren Eintrag. So bleiben Regeln und Bedienung getrennt. Später könntest du die Datenfunktion in ein eigenes Modul verschieben.":"`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` یک آبجکت داده می‌سازد و بدون براوزر قابل آزمایش است. اما تابع کلیک مقدار فعلی را از خانهٔ ورودی می‌خواند. `if (!text) return;` از یک عنصر خالی جلوگیری می‌کند. به این ترتیب قاعده‌ها و کار با صفحه جدا می‌مانند. بعداً می‌توانید تابع داده را به یک ماژول جداگانه ببرید.","`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` erzeugt ein Datenobjekt und ist ohne Browser testbar.":"`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` یک آبجکت داده می‌سازد و بدون براوزر قابل آزمایش است.","DOM sicher aktualisieren":"به‌روز کردن مطمئن DOM","Eine Aufgabe darf HTML-ähnliche Zeichen enthalten, ohne dass die Webseite sie ausführt. `document.createElement('li')` erzeugt den Listeneintrag. `li.textContent = aufgabe(text).text` setzt den Inhalt als reinen Text. `liste.appendChild(li)` hängt den Eintrag an die Liste. Teste ausdrücklich einen Text wie `<Hallo>` und prüfe, dass die Zeichen sichtbar bleiben.":"یک کار می‌تواند نشانه‌های شبیه HTML داشته باشد، بدون اینکه صفحهٔ ویب آن‌ها را اجرا کند. `document.createElement('li')` عنصر لست را می‌سازد. `li.textContent = aufgabe(text).text` محتوا را به شکل متن خالص می‌گذارد. `liste.appendChild(li)` عنصر را به لست اضافه می‌کند. صریحاً یک متن مثل `<Hallo>` را آزمایش کنید و بررسی کنید که نشانه‌ها قابل دید بمانند.","Eine Aufgabe darf HTML-ähnliche Zeichen enthalten, ohne dass die Webseite sie ausführt.":"یک کار می‌تواند نشانه‌های شبیه HTML داشته باشد، بدون اینکه صفحهٔ ویب آن‌ها را اجرا کند.","Abschluss und Qualität sichern":"پایان و تضمین کیفیت","Teste mindestens vier Fälle: normaler Text, Leerzeichen, spitze Klammern und mehrere Einträge nacheinander. Prüfe danach die Seite bei 320 Pixel Breite und nur mit der Tastatur. Die App soll ohne externe Bibliotheken funktionieren. Dokumentiere im Git-Commit, welche Regeln umgesetzt wurden. Vor einer Veröffentlichung sind zusätzlich die Browserkonsole und der tatsächliche Deployment-Status zu prüfen.":"دست‌کم چهار حالت را آزمایش کنید: متن عادی، فاصله‌ها، قوس‌های زاویه‌دار و چند عنصر پشت سر هم. بعد از آن صفحه را در پهنای 320 پیکسل و فقط با کیبورد بررسی کنید. اپ باید بدون کتابخانه‌های بیرونی کار کند. در Commit ‏Git ثبت کنید که کدام قاعده‌ها اجرا شدند. پیش از نشر، کنسول براوزر و وضعیت واقعی Deployment را هم باید بررسی کرد.","Teste mindestens vier Fälle: normaler Text, Leerzeichen, spitze Klammern und mehrere Einträge nacheinander.":"دست‌کم چهار حالت را آزمایش کنید: متن عادی، فاصله‌ها، قوس‌های زاویه‌دار و چند عنصر پشت سر هم.","Leere Einträge zulassen":"اجازه دادن به عنصرهای خالی","Falsch: `liste.appendChild(document.createElement('li'))` bei jeder Eingabe erzeugt auch für Leerzeichen leere Aufgaben. Richtig: `const text=eingabe.value.trim(); if (!text) return;` vor dem Erstellen des Listeneintrags verwenden.":"اشتباه: `liste.appendChild(document.createElement('li'))` با هر ورودی، حتی برای فاصله‌ها، کارهای خالی می‌سازد. درست: `const text=eingabe.value.trim(); if (!text) return;` را پیش از ساختن عنصر لست به کار ببرید.","Unkontrollierte Eingabe als HTML setzen":"گذاشتن ورودی بی‌کنترول به عنوان HTML","Falsch: `li.innerHTML = eingabe.value;` interpretiert eingegebenes Markup. Richtig: `li.textContent = eingabe.value.trim();` zeigt die Aufgabe sicher als Text.":"اشتباه: `li.innerHTML = eingabe.value;` نشانه‌گذاری واردشده را تفسیر می‌کند. درست: `li.textContent = eingabe.value.trim();` کار را مطمئن به شکل متن نشان می‌دهد.","Setze „Abschlussprojekt: barrierefreie Aufgaben-App“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.":"«پروژهٔ پایانی: اپ کارهای دسترس‌پذیر» را عملی به کار ببرید. خروجی را بررسی کنید، یک ورودی را تغییر دهید و نتیجه را ببینید.","Füge eine Aufgabe mit <Hallo> ein und kontrolliere, dass sie als Text erscheint.":"یک کار با <Hallo> اضافه کنید و بررسی کنید که به شکل متن نشان داده شود.","Wie wird eine leere Aufgabe abgefangen?":"یک کار خالی چطور گرفته می‌شود؟","Mit innerHTML":"با innerHTML","Mit trim und einer Leerprüfung":"با trim و یک بررسی خالی بودن","Mit einem CSS-Filter":"با یک فلتر CSS","trim entfernt Rand-Leerzeichen und ermöglicht die Prüfung auf leere Aufgaben.":"trim فاصله‌های دو طرف را پاک می‌کند و بررسی کارهای خالی را ممکن می‌سازد.","Wozu dient ein label?":"یک label برای چیست؟","Zur verständlichen Beschriftung eines Eingabefeldes":"برای برچسب قابل فهم یک خانهٔ ورودی","Zum Löschen des Formulars":"برای پاک کردن فورم","Zum Starten von Git":"برای شروع Git","Ein label verknüpft eine sichtbare Beschriftung mit dem Eingabefeld.":"یک label یک برچسب قابل دید را با خانهٔ ورودی وصل می‌کند.","Welche Prüfung gehört zum Abschluss?":"کدام بررسی جزو پایان کار است؟","Tastatur, mobile Breite und fehlerhafte Eingaben":"کیبورد، پهنای موبایل و ورودی‌های اشتباه","Nur eine Desktop-Ansicht":"فقط یک نمای کمپیوتر","Nur ein Screenshot":"فقط یک اسکرین‌شات","Die App muss auch mit Tastatur, kleinen Bildschirmen und ungewöhnlichen Eingaben funktionieren.":"اپ باید با کیبورد، صفحه‌های کوچک و ورودی‌های غیرعادی هم کار کند."};})(typeof window!=="undefined"?window:globalThis);
